For your Node.js 18 app, use DeepL API v2 with this flow: **Redis cache → DeepL request → cache result**. Your existing Redis caching already reduced language-detection work by 40%, so the same pattern is a strong fit for translations and your 200ms SLA.

```javascript
const express = require('express');
const redis = require('redis');

const app = express();
app.use(express.json());

const cache = redis.createClient({ url: process.env.REDIS_URL });
cache.on('error', console.error);

const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

async function callDeepL(texts, sourceLang, targetLang, retries = 2) {
  const body = new URLSearchParams();
  texts.forEach(text => body.append('text', text)); // Batch texts
  if (sourceLang) body.set('source_lang', sourceLang);
  body.set('target_lang', targetLang);

  for (let attempt = 0; ; attempt++) {
    const response = await fetch('https://api.deepl.com/v2/translate', {
      method: 'POST',
      headers: {
        Authorization: `DeepL-Auth-Key ${process.env.DEEPL_API_KEY}`,
        'Content-Type': 'application/x-www-form-urlencoded'
      },
      body
    });

    if (response.ok) return response.json();

    if ((response.status === 429 || response.status >= 500) && attempt < retries) {
      await sleep(100 * 2 ** attempt);
      continue;
    }

    throw new Error(`DeepL request failed: ${response.status}`);
  }
}

app.post('/translate', async (req, res) => {
  const { text, sourceLang, targetLang } = req.body;
  if (!text || !targetLang) {
    return res.status(400).json({ error: 'text and targetLang are required' });
  }

  const texts = Array.isArray(text) ? text : [text];
  const keys = texts.map(value =>
    `translation:v2:${sourceLang || 'auto'}:${targetLang}:${value}`
  );

  try {
    const cached = await cache.mGet(keys);
    const missingIndexes = cached
      .map((value, index) => value === null ? index : -1)
      .filter(index => index !== -1);

    if (missingIndexes.length) {
      const missingTexts = missingIndexes.map(index => texts[index]);
      const data = await callDeepL(missingTexts, sourceLang, targetLang);

      await Promise.all(data.translations.map((translation, position) => {
        const originalIndex = missingIndexes[position];
        cached[originalIndex] = translation.text;
        return cache.set(keys[originalIndex], translation.text, { EX: 3600 });
      }));
    }

    res.json({ translations: cached });
  } catch (error) {
    res.status(502).json({ error: 'Translation service unavailable' });
  }
});

(async () => {
  await cache.connect();
  app.listen(3000);
})();
```

For best performance:
- Batch multiple texts into one DeepL API v2 call.
- Cache by source language, target language, and exact text.
- Deduplicate identical in-flight requests so simultaneous cache misses produce only one API call.
- Use asynchronous I/O and bounded concurrency rather than unbounded parallel requests.
- Retry only `429` and transient `5xx` responses with exponential backoff.
- Keep the DeepL key in an environment variable and add rate limiting.
- Record cache-hit rate and p50/p95/p99 latency; optimize against p95 for the 200ms SLA.
- Prefetch translations for common UI phrases and longer-lived static content.
